-- PAPER-TAGS-1 (owner directive 2026-10-18, pillar reach): the library files each paper on one shelf, which
-- answers "where does this live" but cannot show that a QEC paper is also a Bruhat-Tits paper, or that a
-- number-theory result is usable for choosing a hardware platform. A shelf is exclusive by design; the
-- interdisciplinary signal and the use cases need a second, multi-label layer.
--
-- paper_tag is that layer: 2-6 tags per paper across three kinds --
--   method  what machinery the paper actually works with (ultrametric, p-adic, stabilizer, law-of-form)
--   topic   what it is about (qubits, cosmology, LLM systems, knowledge integrity)
--   use     what a reader could do with it (choosing a platform, benchmarking energy, teaching, replication)
-- Tags are evidence-based: a tag survives only when the paper's own text supports it (the inflated ones are
-- pruned by keyword), and use tags are the model's judgement about applicability. Assignments are data, like
-- shelves: a wrong tag is one DELETE, no deploy.
CREATE TABLE IF NOT EXISTS tag_registry (
  tag         TEXT PRIMARY KEY,
  kind        TEXT NOT NULL,
  label       TEXT NOT NULL,
  description TEXT NOT NULL,
  sort        INTEGER NOT NULL DEFAULT 100,
  updated_at  TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS paper_tag (
  slug       TEXT NOT NULL,
  tag        TEXT NOT NULL,
  rank       INTEGER NOT NULL DEFAULT 0,
  method     TEXT NOT NULL DEFAULT 'model-pass',
  updated_at TEXT DEFAULT (datetime('now')),
  PRIMARY KEY (slug, tag)
);
CREATE INDEX IF NOT EXISTS idx_paper_tag_tag ON paper_tag(tag);
CREATE INDEX IF NOT EXISTS idx_paper_tag_slug ON paper_tag(slug);

